CREATE TABLE IF NOT EXISTS announcements (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), title TEXT NOT NULL, body TEXT NOT NULL, audience TEXT NOT NULL, class_id TEXT REFERENCES classes(id), student_ids_json TEXT, emergency INTEGER NOT NULL DEFAULT 0, sender_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), type TEXT NOT NULL, recipient_id TEXT NOT NULL REFERENCES users(id), student_id TEXT REFERENCES student_profiles(id), title TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, created_by TEXT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), sender_id TEXT NOT NULL REFERENCES users(id), recipient_id TEXT NOT NULL REFERENCES users(id), student_id TEXT NOT NULL REFERENCES student_profiles(id), body TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS calendar_events (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), event_type TEXT NOT NULL, title TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT, audience TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notification_preferences (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), user_id TEXT NOT NULL REFERENCES users(id), settings_json TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, user_id));
CREATE TABLE IF NOT EXISTS communication_delivery_log (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), channel TEXT NOT NULL, provider TEXT, message_id TEXT, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_notifications_recipient ON notifications(school_id, recipient_id, status);
CREATE INDEX IF NOT EXISTS idx_messages_participants ON messages(school_id, sender_id, recipient_id, student_id);
